using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Windows.Forms;using System.Xml.Serialization;
namespace ShotOut {
public class RecentProject {public string Path;public DateTime OpenedUtc;}
public class ProjectHistory {
public List<RecentProject> Items=new List<RecentProject>();public List<string> Assets=new List<string>();
static ProjectHistory current;
internal static string TestFolder;
internal static string Root {get{return Preferences.Testing?TestFolder:System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Preferences.FilePath),"Library");}}
internal static ProjectHistory Current {get{if(current!=null)return current;current=new ProjectHistory();try{if(Root!=null){string path=System.IO.Path.Combine(Root,"recent-projects.xml");if(File.Exists(path)&&new FileInfo(path).Length<131072)using(var stream=File.OpenRead(path))current=(ProjectHistory)new XmlSerializer(typeof(ProjectHistory)).Deserialize(stream);}}catch(Exception){current=new ProjectHistory();}current.Items=(current.Items??new List<RecentProject>()).Where(item=>item!=null&&!String.IsNullOrWhiteSpace(item.Path)).Take(24).ToList();current.Assets=(current.Assets??new List<string>()).Where(path=>!String.IsNullOrWhiteSpace(path)).Distinct(StringComparer.OrdinalIgnoreCase).Take(64).ToList();return current;}}
internal static void Reset(){current=null;}
internal static string ThumbnailPath(string path){if(Root==null)return null;using(var hash=SHA256.Create())return System.IO.Path.Combine(Root,BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(path).ToUpperInvariant()))).Replace("-","")+".png");}
internal static void Save(){if(Root==null)return;try{Directory.CreateDirectory(Root);string data=System.IO.Path.Combine(Root,"recent-projects.xml"),temp=data+".tmp";using(var stream=File.Create(temp))new XmlSerializer(typeof(ProjectHistory)).Serialize(stream,Current);if(File.Exists(data))File.Replace(temp,data,null);else File.Move(temp,data);}catch(IOException){}catch(UnauthorizedAccessException){}}
internal static void RememberAsset(string path){path=System.IO.Path.GetFullPath(path);var store=Current;store.Assets.RemoveAll(item=>String.Equals(item,path,StringComparison.OrdinalIgnoreCase));store.Assets.Insert(0,path);store.Assets=store.Assets.Take(64).ToList();Save();}

internal static void Remember(string path,Bitmap preview){
path=System.IO.Path.GetFullPath(path);var store=Current;store.Items.RemoveAll(item=>String.Equals(item.Path,path,StringComparison.OrdinalIgnoreCase));store.Items.Insert(0,new RecentProject {Path=path,OpenedUtc=DateTime.UtcNow});var removed=store.Items.Skip(24).ToArray();store.Items=store.Items.Take(24).ToList();if(Root==null)return;
try{Directory.CreateDirectory(Root);foreach(var item in removed){string old=ThumbnailPath(item.Path);if(File.Exists(old))File.Delete(old);}Save();
if(preview!=null)using(var thumb=new Bitmap(144,100)){using(var graphics=Graphics.FromImage(thumb)){graphics.Clear(Color.FromArgb(32,35,42));float scale=Math.Min(136f/preview.Width,92f/preview.Height);graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;graphics.DrawImage(preview,(144-preview.Width*scale)/2,(100-preview.Height*scale)/2,preview.Width*scale,preview.Height*scale);}thumb.Save(ThumbnailPath(path),System.Drawing.Imaging.ImageFormat.Png);}}
catch(IOException){}catch(UnauthorizedAccessException){}catch(System.Runtime.InteropServices.ExternalException){}
}
}
class CanvasPresetButton : ModernButton {
internal Size CanvasSize {get;set;}internal string PresetName;
protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;float scale=Math.Min(94f/CanvasSize.Width,42f/CanvasSize.Height);float w=CanvasSize.Width*scale,h=CanvasSize.Height*scale;var r=new RectangleF((Width-w)/2,8+(42-h)/2,w,h);using(var fill=new SolidBrush(Color.FromArgb(45,57,81)))using(var pen=new Pen(Color.FromArgb(140,170,240),1.5f)){g.FillRectangle(fill,r);g.DrawRectangle(pen,r.X,r.Y,r.Width,r.Height);}TextRenderer.DrawText(g,PresetName,Font,new Rectangle(2,53,Width-4,20),ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(g,CanvasSize.Width+" × "+CanvasSize.Height,Font,new Rectangle(2,74,Width-4,20),Color.FromArgb(164,176,196),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
}
partial class Editor {
bool projectLibrary;string librarySort="Newest";ModernButton imagesLibraryButton,projectsLibraryButton;FontPicker librarySortChoice;
static bool IsProjectPath(string path){string extension=Path.GetExtension(path);return extension.Equals(".shotout",StringComparison.OrdinalIgnoreCase)||extension.Equals(".snapcanvas",StringComparison.OrdinalIgnoreCase);}
void RecordRecentProject(string path){ProjectHistory.Remember(path,Preview);}
void InstallLibraryTabs(Panel library){
var tabs=new FlowLayoutPanel {Dock=DockStyle.Top,Height=44,WrapContents=false};imagesLibraryButton=ActionButton("Images",null,"Browse screenshot images",delegate{SetLibraryType(false);},88);projectsLibraryButton=ActionButton("Projects",null,"Recent projects and projects in this folder",delegate{SetLibraryType(true);},96);tabs.Controls.Add(imagesLibraryButton);tabs.Controls.Add(projectsLibraryButton);imagesLibraryButton.Selected=true;
var search=ActionButton("Search · Ctrl+K","Search","Search files, open tabs and annotations (Ctrl+K)",ShowQuickSearch,175);tabs.Controls.Add(search);
librarySortChoice=new FontPicker {Width=135,Height=34,Text="Newest   ▾",ForeColor=text,BackColor=Color.FromArgb(43,46,54),Margin=new Padding(3),AccessibleName="Sort library"};librarySortChoice.Items.AddRange(new[]{"Newest","Oldest","Name A–Z","Name Z–A"});librarySortChoice.SelectedItem=librarySort;librarySortChoice.SelectedIndexChanged+=delegate{librarySort=librarySortChoice.SelectedItem;screenshotPage=0;RefreshScreenshotBrowser();};tabs.Controls.Add(librarySortChoice);
tabs.Controls.Add(new Label {Text="Drop images or projects here",Width=230,Height=36,ForeColor=muted,TextAlign=ContentAlignment.MiddleLeft});library.Controls.Add(tabs);library.Controls.SetChildIndex(tabs,library.Controls.Count-1);
welcome.AllowDrop=true;welcome.DragEnter+=delegate(object sender,DragEventArgs e){if(e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;};welcome.DragDrop+=delegate(object sender,DragEventArgs e){var paths=e.Data.GetData(DataFormats.FileDrop) as string[];if(paths!=null)foreach(string path in paths)Guard(delegate{OpenPath(path);});};
}
void SetLibraryType(bool projects){bool changed=projectLibrary!=projects;projectLibrary=projects;if(changed)screenshotBrowsing=LibraryHome();screenshotPage=0;imagesLibraryButton.Selected=!projects;projectsLibraryButton.Selected=projects;imagesLibraryButton.Invalidate();projectsLibraryButton.Invalidate();RefreshScreenshotBrowser();}
static DateTime LibraryDate(string path,Dictionary<string,DateTime> recents){DateTime recent;if(recents.TryGetValue(path,out recent))return recent;try{return File.GetLastWriteTimeUtc(path);}catch{return DateTime.MinValue;}}
static string[] ReadLibraryEntries(string folder,int page,bool projects,string sorting,RecentProject[] recent){
var paths=new List<string>();if(Directory.Exists(folder)){paths.AddRange(Directory.EnumerateDirectories(folder));paths.AddRange(Directory.EnumerateFiles(folder).Where(path=>screenshotExtensions.Contains(Path.GetExtension(path).ToLowerInvariant())&&IsProjectPath(path)==projects));}if(projects)paths.AddRange(recent.Where(item=>File.Exists(item.Path)).Select(item=>item.Path));var dates=recent.GroupBy(item=>item.Path,StringComparer.OrdinalIgnoreCase).ToDictionary(group=>group.Key,group=>group.Max(item=>item.OpenedUtc),StringComparer.OrdinalIgnoreCase);IEnumerable<string> ordered=paths.Distinct(StringComparer.OrdinalIgnoreCase);if(sorting=="Name A–Z")ordered=ordered.OrderBy(path=>!Directory.Exists(path)).ThenBy(Path.GetFileName,StringComparer.CurrentCultureIgnoreCase);else if(sorting=="Name Z–A")ordered=ordered.OrderBy(path=>!Directory.Exists(path)).ThenByDescending(Path.GetFileName,StringComparer.CurrentCultureIgnoreCase);else if(sorting=="Oldest")ordered=ordered.OrderBy(path=>!Directory.Exists(path)).ThenBy(path=>LibraryDate(path,dates));else ordered=ordered.OrderBy(path=>!Directory.Exists(path)).ThenByDescending(path=>LibraryDate(path,dates));return ordered.Skip(Math.Max(0,page)*200).Take(201).ToArray();
}
void InstallVisualCanvasPresets(){
blankCanvasMenu=PopupLifetime.Own(this,DarkMenu());var grid=new FlowLayoutPanel {Size=new Size(480,208),BackColor=panel,Margin=Padding.Empty,Padding=Padding.Empty,WrapContents=true};foreach(var preset in blankPresets){var size=preset.Value;var button=new CanvasPresetButton {CanvasSize=size,PresetName=preset.Key,AccessibleName=preset.Key+" "+size.Width+" × "+size.Height,Text="",Size=new Size(154,98),Margin=new Padding(3),BackColor=Color.FromArgb(43,46,54),ForeColor=text,Font=Font};button.Click+=delegate{blankCanvasMenu.Close();PopupLifetime.AfterClick(this,delegate{Guard(delegate{CreateBlankCanvas(size);});});};grid.Controls.Add(button);}blankCanvasMenu.Items.Add(new ToolStripControlHost(grid){AutoSize=false,Size=grid.Size,Margin=Padding.Empty,Padding=Padding.Empty});blankCanvasMenu.Items.Add(new ToolStripSeparator());blankCanvasMenu.Items.Add("Custom size…",null,delegate{PopupLifetime.AfterClick(this,delegate{using(var dialog=new BlankCanvasSizeDialog())if(dialog.ShowDialog(this)==DialogResult.OK)Guard(delegate{CreateBlankCanvas(dialog.SelectedSize);});});});
}
}
}